"""Trusted-owner standalone inventory/copy probe; generated bytes remain private outputs."""
import hashlib
from itertools import chain
import json
import os
from pathlib import Path
import shutil
import stat
import sys

ROOT = Path(__file__).resolve().parent.parent

def digest(raw):
    return "sha256:" + hashlib.sha256(raw).hexdigest()

def encoded(rows):
    return json.dumps(rows, sort_keys=True, separators=(",", ":")).encode()

def inventory(base):
    base = Path(base)
    assert base.is_dir() and not base.is_symlink(), "STANDALONE_ROOT"
    rows = {}
    total = 0
    for path in chain([base], base.rglob("*")):
        assert len(rows) < 32768, "STANDALONE_ENTRY_BOUND"
        name = "." if path == base else path.relative_to(base).as_posix()
        before = path.lstat()
        if stat.S_ISLNK(before.st_mode):
            target = os.readlink(path)
            assert len(target.encode()) <= 8192, "STANDALONE_LINK_BOUND"
            rows[name] = dict(kind="symlink", target=target, targetFollowed=False)
        elif stat.S_ISDIR(before.st_mode):
            rows[name] = dict(kind="directory", mode=stat.S_IMODE(before.st_mode))
        else:
            assert stat.S_ISREG(before.st_mode), "STANDALONE_SPECIAL_FILE"
            total += before.st_size
            assert total <= 1024**3, "STANDALONE_BYTE_BOUND"
            with path.open("rb") as source:
                value = "sha256:" + hashlib.file_digest(source, "sha256").hexdigest()
            after = path.lstat()
            assert (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns, before.st_mode) == (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns, after.st_mode), "STANDALONE_CHANGED_DURING_HASH"
            rows[name] = dict(kind="file", mode=stat.S_IMODE(before.st_mode), bytes=before.st_size, digest=value)
    return rows

def summary(rows):
    return dict(entries=len(rows), files=sum(v["kind"] == "file" for v in rows.values()),
                symlinks=sum(v["kind"] == "symlink" for v in rows.values()),
                bytes=sum(v.get("bytes", 0) for v in rows.values()),
                inventoryDigest=digest(encoded(rows)), symlinkTargetsFollowed=False)

def changed_summary(before, after):
    changed = {name for name in set(before) | set(after) if before.get(name) != after.get(name)}
    categories = {"cache": 0, "diagnostics": 0, "server-rendered": 0, "other": 0}
    kinds = {"added": 0, "removed": 0, "changed": 0}
    for name in changed:
        category = ("cache" if name == ".next/cache" or name.startswith(".next/cache/") else
                    "diagnostics" if name in {".next/trace", ".next/trace-build"} or name.startswith(".next/diagnostics/") else
                    "server-rendered" if name.startswith(".next/server/") else "other")
        categories[category] += 1
        kinds["added" if name not in before else "removed" if name not in after else "changed"] += 1
    return dict(changedEntries=len(changed), categories=categories, changes=kinds,
                before=summary(before), after=summary(after), detailedInventoryPublished=False)

def copy_bound(descriptor, target):
    assert set(descriptor) == {"profile", "privateSourceRoot", "privateInventoryPath", "inventoryDigest", "producer"}, "STANDALONE_DESCRIPTOR"
    assert descriptor["profile"] == "patamaps-standalone-owner-probe-1", "STANDALONE_DESCRIPTOR"
    source = Path(descriptor["privateSourceRoot"])
    raw = Path(descriptor["privateInventoryPath"]).read_bytes()
    assert len(raw) < 16 * 1024**2 and digest(raw) == descriptor["inventoryDigest"], "STANDALONE_INVENTORY_CHANGED"
    expected = json.loads(raw)
    assert inventory(source) == expected, "STANDALONE_SOURCE_CHANGED"
    shutil.copytree(source, target, symlinks=True)
    assert inventory(target) == expected and inventory(source) == expected, "STANDALONE_COPY_CHANGED"

def helper_main():
    mode = sys.argv[1]
    if mode == "--seed":
        Path("bundle").mkdir()
        Path("bundle/previous.txt").write_text("previous-selected-generation\n")
    elif mode == "--verify-seed":
        assert Path("bundle/previous.txt").read_text() == "previous-selected-generation\n"
    elif mode == "--copy":
        copy_bound(json.loads(Path("descriptor.json").read_bytes()), Path("bundle"))
    elif mode == "--verify-copy":
        descriptor = json.loads(Path("descriptor.json").read_bytes())
        raw = Path(descriptor["privateInventoryPath"]).read_bytes()
        assert digest(raw) == descriptor["inventoryDigest"], "STANDALONE_INVENTORY_CHANGED"
        assert inventory(Path("bundle")) == json.loads(raw), "STANDALONE_COPY_CHANGED"
    elif mode == "--fail":
        raise SystemExit(9)
    else:
        raise AssertionError("STANDALONE_HELPER_MODE")
    print("standalone-private-output-check-passed")

def observe(cli, standalone, work, evidence, run, producer):
    rows = inventory(standalone)
    observed = summary(rows)
    (evidence/"standalone-probe.json").write_text(json.dumps(dict(
        status="observed-private-tree-before-native-selection", producedTree=observed,
        detailedInventoryPublished=False, rawGeneratedOutputsPublished=False,
        producerSourceAndToolsUnavailable=False, fullRetainedBundleAccepted=False), indent=2)+"\n")
    private_inventory = work / "private-standalone-inventory.json"
    private_inventory.write_bytes(encoded(rows))
    private_inventory.chmod(0o600)
    owner = work / "standalone-selection-owner"
    owner.mkdir()
    identity = "urn:qualification:chatbot:standalone-output-probe"
    values = {
        "graph.json": dict(schemaVersion="0.1.0", documentType="graph", id=identity+":source",
            namespace="standalone-output-probe", revision="1",
            entities=[dict(id=identity+":runtime", kind="standalone-runtime", label="Pinned Next standalone",
                           attributes=producer)], mappings=[], authorities=[]),
        "policy.json": dict(schemaVersion="0.1.0", documentType="policy", id=identity+":policy",
            graph=dict(id=identity, revision="1"), mappings=[], constraints=[], evidence=[]),
        "projection.json": dict(schemaVersion="0.1.0", documentType="projection-spec", id=identity+":projection",
            select=dict(kinds=["standalone-runtime"]), slots=[]),
        "descriptor.json": dict(profile="patamaps-standalone-owner-probe-1",
            privateSourceRoot=str(standalone), privateInventoryPath=str(private_inventory),
            inventoryDigest=observed["inventoryDigest"], producer=producer),
    }
    for name, value in values.items():
        (owner/name).write_text(json.dumps(value, indent=2)+"\n")
    (owner/"copy-helper.py").write_bytes(Path(__file__).read_bytes())
    project = dict(profile="patamaps-project-inputs-1", id=identity+":inputs", nonsecretInputs=True,
        inputs=[*values, "copy-helper.py"], components=[dict(id="producer", kind="deployment",
        root=".", entrypoints=["descriptor.json"])], nonsecretConfiguration={}, secretReferences={})
    workspace = dict(schemaVersion="0.1.0", documentType="workspace-config", id=identity,
        namespace="standalone-output-probe", revision="1", packs=[],
        sources=[dict(adapter="portable-shard", id=identity+":source", path="graph.json")],
        policy="policy.json", projections=[dict(path="projection.json",
            emissions=[dict(path="generated/standalone.json", language="json")])],
        context=dict(scope="Private produced-output observation; no complete build/dependency closure"),
        evaluatedAt="2026-10-24T00:00:00Z")
    def command(mode):
        return dict(profile="patamaps-project-command-1", workingDirectory=".", environmentReferences={},
            invocation=dict(executable=sys.executable, arguments=["copy-helper.py", mode],
                codeInputs=["copy-helper.py"], bounds=dict(maximumElapsedMs=120000,
                maximumStdoutBytes=4096, maximumStderrBytes=4096)))
    def plan(label, build, verify, kind="tree"):
        path = work/("standalone-"+label+".json")
        path.write_text(json.dumps(dict(profile="patamaps-project-build-1",
            maximumRetainedAttempts=8, project=project, workspace=workspace,
            buildSteps=[command(build)], verificationSteps=[command(verify)],
            outputs=[dict(path="bundle", kind=kind)]), indent=2)+"\n")
        return path
    state = work/"standalone-selection-state"
    def native(label, path, expected=0):
        return json.loads(run(label, [cli, "project-build", path, "--source", owner,
            "--state", state], expected=expected))
    seed = native("standalone-prior-selection", plan("prior", "--seed", "--verify-seed"))
    assert seed["status"] == "selected-project-build"
    pointer = (state/"selected.json").read_bytes()
    generated = native("standalone-actual-native-output", plan("actual", "--copy", "--verify-copy"),
                       1 if observed["symlinks"] else 0)
    if observed["symlinks"]:
        assert generated["status"] == "refused-project-build" and generated["previousSelectionPreserved"]
        assert "PROJECT_BUILD_OUTPUT_SYMLINK" in generated["reason"]
        assert (state/"selected.json").read_bytes() == pointer
    else:
        assert generated["status"] == "selected-project-build"
        pointer = (state/"selected.json").read_bytes()
        failed = native("standalone-failed-selection", plan("failed", "--fail", "--verify-copy"), 1)
        assert failed["previousSelectionPreserved"] and (state/"selected.json").read_bytes() == pointer
    closed = native("standalone-closed-tree-select",
                    plan("closed", "--copy", "--verify-copy", kind="closed-tree"))
    assert closed["status"] == "selected-project-build"
    verified = json.loads(run("standalone-final-native-selection-verify", [cli, "project-build-verify", state]))
    assert verified["status"] == "verified-selected-build-bindings"
    assert inventory(standalone) == rows
    report = dict(status="observed-standalone-native-output-boundary", producedTree=observed,
        nativeTreeSelected=not bool(observed["symlinks"]),
        closedTreeSelected=True, closedTreeAttempt=closed["attempt"], closedTreeState=str(state),
        generatedSymlinkRefused=bool(observed["symlinks"]), previousSelectionPreserved=True,
        priorAndFinalSelectionVerified=True, exactPrivateCopyVerified=True,
        detailedInventoryPublished=False, rawGeneratedOutputsPublished=False,
        producerSourceAndToolsUnavailable=False, fullRetainedBundleAccepted=False,
        sourceBuildLineage=producer, helperDigest=digest(Path(__file__).read_bytes()), filesDeleted=0)
    (evidence/"standalone-probe.json").write_text(json.dumps(report, indent=2)+"\n")
    return report

if __name__ == "__main__":
    helper_main()
